# 10 músicas de brincadeiras de infância (originais). Receita tirada do estudo do Morto-Vivo (Animadinhos):
# anúncio da brincadeira + regra simples que a criança obedece + resposta em coro + verso de recompensa. Só palavras reais, com rima.
def make(S):
    I = "gentle ukulele strums, soft hand claps, bright glockenspiel, light shaker, soft bouncy bass, sweet kids choir answering the commands"
    D = {
    11: ("Estátua!", "estatua", 108, "C major",
         "Música tocando, a gente vai dançar,\nmúsica parando, estátua vai ficar!\nUm, dois, três, não pode se mexer,\nestátua bonita, é só esperar e ver!",
         "Mexe os bracinhos, mexe o pezinho,\ngira a cabeça, devagarinho,\nmexe a barriga, balança o corpão,\nagora parou, não se mexe, não!",
         "Estátua de leão, estátua de ursinho,\nninguém se mexe nem um pouquinho,\na música voltou, vamos dançar,\nquem ficou parado, vem brincar!",
         "Dança, dança, dança,\nparou, parou, parou,\ndança, dança, dança,\na música voltou!"),
    12: ("Esconde-Esconde", "esconde-esconde", 104, "G major",
         "Eu fecho os olhos e vou contar,\nvocês se escondem, vou procurar,\natrás da cortina, no armário também,\nonde será que você está, meu bem?",
         "Será que está embaixo da mesa?\nProcurei com toda a certeza,\nserá que está atrás do portão?\nAchei um pezinho, bem no chão!",
         "Achei, achei, que alegria,\nagora é a vez da sua folia,\nvocê conta devagarinho,\ne eu me escondo, bem quietinho!",
         "Um, dois, três, quatro, cinco,\njá vou, já vou, já vou,\num, dois, três, quatro, cinco,\nachei, achei, achou!"),
    13: ("Pega-Pega", "pega-pega", 112, "D major",
         "Corre, corre, que eu vou te pegar,\ncorre, corre, não vai me alcançar,\npega-pega, pega-pega, vamos brincar,\nquem foi pego, agora vai pegar!",
         "Corre pra frente, corre pra trás,\nninguém me pega, ninguém me faz,\ncorre no jardim, corre no quintal,\nque brincadeira especial!",
         "Peguei, peguei, agora é você,\nvem me pegar, eu quero ver,\nbate no ombro, só de mansinho,\nagora é você, corre devagarinho!",
         "Um, dois, três, lá vou eu,\nquem fugir, não se perdeu,\num, dois, três, é a brincadeira,\ncorrendo a tarde inteira!"),
    14: ("Batata Quente", "batata-quente", 112, "F major",
         "Batata quente, quente, quente,\npassa pro amigo ali na frente,\nbatata quente, quente, quente,\nquem ficar com ela, fica contente!",
         "Passa rápido, passa pro lado,\nnão demora, não fique parado,\na batata esquentou demais,\npassa pro outro, passa pra trás!",
         "A música parou de repente,\nquem está com a batata, levanta contente,\ndá um pulinho, dá uma voltinha,\ne volta pra roda, bem fofinha!",
         "Passa, passa, passa,\nquente, quente, quente,\npassa, passa, passa,\nparou, parou, gente!"),
    15: ("Amarelinha", "amarelinha", 104, "C major",
         "Pula no um, pula no dois,\npula no três, e volta depois,\namarelinha, amarelinha,\npula num pé, bem direitinha!",
         "Joga a pedrinha, olha onde vai,\ncai no quadrado e não sai,\npula num pé, bem de levinho,\nsegura o equilíbrio, devagarinho!",
         "Chegou no céu, que alegria,\ntodo mundo bate palma e assovia,\nagora é a vez do amiguinho,\npula contente, no seu caminho!",
         "Um, dois, três, pula outra vez,\nquatro, cinco, seis, é a sua vez,\nsete, oito, nove, dez,\nchegou no céu, olha só, vocês!"),
    16: ("Pula Corda", "pula-corda", 116, "G major",
         "A corda gira, gira, gira,\npula, pula, que ela não te tira,\na corda sobe, a corda desce,\npula com força, ninguém esquece!",
         "Um pulinho, dois pulinhos,\npula bem de levinho,\ntrês pulinhos, quatro pulinhos,\npula na ponta do pezinho!",
         "Entra na corda, bem devagar,\npula sem pressa, vai pular,\nsai da corda, sem tropeçar,\nagora é a vez de outro pular!",
         "Pula, pula, pula, pula,\na corda gira, ninguém se cansa,\npula, pula, pula, pula,\npula corda e dança!"),
    17: ("Dança das Cadeiras", "danca-das-cadeiras", 112, "F major",
         "Roda, roda, roda a cadeira,\ndança, dança, a tarde inteira,\nquando a música acabar,\ncorre e senta, vai sentar!",
         "Uma cadeira a menos, é a regra,\nquem não sentou também se alegra,\ndança de novo, vem com a gente,\ntodo mundo brinca contente!",
         "A música parou, olha a pressa,\ncorre pra cadeira, que beleza,\nquem sentou bate uma palma,\nquem não sentou, torce com a alma!",
         "Dança, dança, dança, dança,\na música vai parar,\ndança, dança, dança, dança,\ncorre e vai sentar!"),
    18: ("O Mestre Mandou", "o-mestre-mandou", 108, "C major",
         "O mestre mandou, mandou, mandou,\nlevanta as mãos, que ele falou,\no mestre mandou, mandou, mandou,\ndá um pulinho, e todo mundo pulou!",
         "O mestre mandou: bate palma,\no mestre mandou: pé no chão,\no mestre mandou: dá uma volta,\ne fecha os olhos, sem confusão!",
         "Só vale se o mestre mandou,\nse ele não falou, não vale, não,\nescuta com muita atenção,\nquem errou, ri, não tem confusão!",
         "Mão pra cima, mão pra baixo,\npé pra frente, pé pra trás,\no mestre mandou, vai com jeito,\no mestre mandou, mais e mais!"),
    19: ("Cabra-Cega", "cabra-cega", 100, "G major",
         "Olhinhos tapados, vou procurar,\nquem está por perto, vou encontrar,\ndá um passinho, dá outro também,\ndevagar, devagar, vai com jeito, meu bem!",
         "Estica o bracinho, tateia no ar,\nonde será que alguém vai estar?\nEscuto uma risadinha ali,\nvem de lá, vem de lá, é por aqui?",
         "Achei você, que alegria,\na venda agora é de quem sorria,\namarra com jeito, bem devagar,\nagora é você que vai procurar!",
         "Pra lá, pra cá, pra lá, pra cá,\nquem será que eu vou achar?\nPra lá, pra cá, pra lá, pra cá,\ncheguei, cheguei, vou te abraçar!"),
    20: ("Telefone Sem Fio", "telefone-sem-fio", 108, "D major",
         "Cochicha no ouvido, bem baixinho,\npassa pra frente, devagarinho,\ntelefone sem fio, vai passar,\na mensagem vai chegar!",
         "O primeiro cochicha pro segundo,\no segundo cochicha pro terceiro,\na palavra vai rodando pelo mundo,\ne chega no final, bem ligeiro!",
         "O último escuta e fala bem alto,\na palavra mudou, que sobressalto!\nEra gato, virou pato,\ntodo mundo ri, que barato!",
         "Baixinho, baixinho, vai passando,\nouvidinho atento, vai escutando,\nbaixinho, baixinho, vai passando,\nde boca em boca, vai rodando!"),
    }
    out = {}
    for n, (t, sl, bpm, key, c, v1, v2, b) in D.items():
        out[n] = dict(titulo=t, slug=sl, bpm=bpm, key=key, inst=I, lyr=S(c, v1, v2, b, False))
    return out
